head.script:
scwin.gVar = {
    "cValue" : "",
    "cDisplaymessage" : "",
    "cInvalidMessage" : "",
    "cInvalidMessageFunc" : "",
    "strFailType" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > M > validate]<br/>입력값에 대한 유효성 체크를 실행한 후 결과값을 반환합니다.",
    "validation" : [
        "displaymessage=true 인 경우 유효성 체크를 통과하지 못한 속성에 대한 실패 메시지가 출력되며, invalidMessage, invalidMessageFunc 속성으로 실패 메시지를 변경할 수 있습니다.",
        "실패 메시지가 출력된 후 false 를 반환합니다.",
        "유효성 체크를 통과하지 못한 컴포넌트가 포커스 됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 은 코드값, 자체 값 selectbox 는 value / 빈 항목은 인덱스)
    con_displaymessage.setValue("2");
    con_value.setValue("abc");
    con_invalidMessageFunc.setSelectedIndex(0);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 mandatory=true, maxlength=2 로 고정합니다 (빈값은 mandatory 실패, abc 는 maxlength 실패, ab 는 통과)\n[절차] displaymessage, 입력값 (필요 시 invalidMessage, invalidMessageFunc) 선택 -> Target 재생성 -> validate 버튼 클릭\n[확인] alert 창의 표시 여부와 문구 (시스템 기본 메시지 / invalidMessage / 사용자 정의 함수 반환값), alert 을 닫은 뒤 결과창에 출력되는 onfocus 줄, validate() 반환값, 포커스 요소"', '', 'label1');

    // 조건 설정
    scwin.gVar["cValue"] = con_value.getValue();
    scwin.gVar["cDisplaymessage"] = con_displaymessage.getText();
    scwin.gVar["cInvalidMessage"] = con_invalidMessage.getValue();
    scwin.gVar["cInvalidMessageFunc"] = con_invalidMessageFunc.getValue();

    let properties = {
        mandatory : "true",
        maxlength : "2",
        displaymessage : scwin.gVar["cDisplaymessage"],
        invalidMessage : scwin.gVar["cInvalidMessage"],
        invalidMessageFunc : scwin.gVar["cInvalidMessageFunc"],
    }

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출
    await $c.gcm.createBasicSecret(cList, 'ev:onfocus="scwin.target1_onfocus"');

    // 헬퍼가 넣은 초기값 secret 을 선택한 입력값으로 덮음 (maxlength 가 걸려 있어도 setValue 값은 잘리지 않음)
    if (scwin.gVar["cValue"] === "empty")
        target1.setValue("");
    else
        target1.setValue(scwin.gVar["cValue"]);
}



// 미설정 표기 변환
scwin.fn_disp = function (strValue) {
    return (strValue === "") ? "미설정" : strValue;
}



// validate 실행 - validation 1, 2, 3 판정 출력
scwin.btn_validate_onclick = function (e) {
    let strValue = target1.getValue() || "";

    scwin.gVar["strFailType"] = "";

    // alert (실패 메시지) 이 닫힌 뒤 반환값이 넘어옴
    let rtn = target1.validate();

    let objActive = document.activeElement;
    let strActive = (objActive && objActive.id) ? objActive.id : "없음";

    let strRtn = "displaymessage " + scwin.fn_disp(scwin.gVar["cDisplaymessage"])
               + " / invalidMessage " + scwin.fn_disp(scwin.gVar["cInvalidMessage"])
               + " / invalidMessageFunc " + scwin.fn_disp(scwin.gVar["cInvalidMessageFunc"])
               + " / 입력값 " + strValue.length + "자"
               + " -> validate() 반환값 : " + rtn
               + " / 포커스 요소 : " + strActive;

    // invalidMessageFunc 설정 시 실패 속성(getType) 병기
    if (scwin.gVar["strFailType"] !== "")
        strRtn += " / 실패 속성 : " + scwin.gVar["strFailType"];

    wf_body_bottom.getObj("scwin").setReturnValue(strRtn);
}



// invalidMessageFunc 로 설정되는 사용자 정의 메시지 함수 - validation 1 판정
scwin.fn_msg = function () {
    scwin.gVar["strFailType"] = this.getType();

    return "invalidMessageFunc 메시지 (원인 : " + this.getType() + ")";
}



// target1 포커스 - validation 3 판정 출력
scwin.target1_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ target1 onfocus 발생");
}
